#!/usr/bin/env python3
"""
Round 139b (culprits), 2 October 2026. Needs round 138b.

Fish caught and farmed, country by country (FAO FishStat).

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 139b (2 October)\n\nNeeds round 138b. Tiles patch round139b_tiles.py beside it. No app.js?v= bump.\n\n- fao_capture and fao_aquaculture (route country): tonnes caught and farmed by\n  each country in FAO's latest year, with ten years before, sea and inland\n  (or fresh, brackish, sea), FAO's groups of animals, the top 15 species and\n  animals FAO counts by head (whales, seals). Under Meat > Marine meats (Wild-\n  caught fish; Fish and shrimp farms) and Oceans > Fishing. Tiles\n  fao_fisheries.py reads the newest Capture_*.zip and Aquaculture_*.zip from\n  FAO's own listing (fao.org/fishery/static/Data/, CC BY-NC-SA 3.0 IGO).\n- Researched, not built: Sea Around Us (catch with unreported, illegal and\n  discards; CC BY-NC) sits in an S3 bucket whose files are not documented;\n  Global Fishing Watch's trawler effort needs a free API token (a repo secret).\n\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round139b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 138b" not in h.read_text(encoding="utf-8"):
        sys.exit("round139b: round 138b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round139b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round139b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round139b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
